using System.Net;
using System.Text.Json;
using Quill.Windows;
using Xunit;
namespace Quill.Windows.Tests;
public sealed class KeySetupTests {
 private const string Good = "AIza012345678901234567890123456789";
 [Theory][InlineData(Provider.Gemini,Good,true)][InlineData(Provider.Gemini,"AQ.012345678901234567890",true)][InlineData(Provider.Groq,"gsk_012345678901234567890",true)][InlineData(Provider.OpenRouter,"sk-or-012345678901234567890",true)][InlineData(Provider.Gemini,"AIza...012345678901234567890",false)][InlineData(Provider.Groq,"gsk_short",false)][InlineData(Provider.Groq,"gsk_01234567890123456789!",false)][InlineData(Provider.Gemini,"gsk_012345678901234567890",false)]
 public void GuidedKeyPlausibilityMatchesAndroid(Provider provider,string value,bool valid) => Assert.Equal(valid,KeySetupSession.Plausible(provider,value));
 [Fact] public void CustomCredentialRemainsEndpointBoundAndMayBeShort() { Assert.True(KeySetupSession.Plausible(Provider.Custom,"abc","https://example.test/v1")); Assert.False(KeySetupSession.Plausible(Provider.Custom,"abc","http://example.test/v1")); }
 [Fact] public void DraftsAreEncryptedSeparatedAndExpansionDoesNotChangeSpeech() {
  using var f = new TestFolder(); var s = new SettingsStore(f.Path); var drafts = new KeySetupDraftStore(f.Path); Assert.Equal("Gemini",drafts.Expanded()); drafts.Write(Provider.Gemini,Good); drafts.Write(Provider.Groq,"gsk_draft"); drafts.Expand("Groq");
  var read = new KeySetupDraftStore(f.Path); Assert.Equal(Good,read.Read(Provider.Gemini)); Assert.Equal("gsk_draft",read.Read(Provider.Groq)); Assert.Equal("Groq",read.Expanded()); Assert.Equal(Provider.Groq,s.Value.Provider); Assert.DoesNotContain(Good,File.ReadAllText(Path.Combine(f.Path,"key-setup.dpapi.json"))); drafts.Write(Provider.Gemini,""); Assert.Empty(drafts.Read(Provider.Gemini)); Assert.Equal("gsk_draft",drafts.Read(Provider.Groq));
 }
 [Fact] public void CustomDraftsNeverFollowChangedHostOrPath() { using var f = new TestFolder(); var d = new KeySetupDraftStore(f.Path); d.Write(Provider.Custom,"abc","https://example.test/one"); Assert.Equal("abc",d.Read(Provider.Custom,"https://EXAMPLE.test/one/")); Assert.Empty(d.Read(Provider.Custom,"https://example.test/two")); Assert.Empty(d.Read(Provider.Custom,"https://other.test/one")); }
 [Fact] public void ClearingSavedSecretsAlsoClearsEncryptedDraftsAndExpansion() { using var f = new TestFolder(); var drafts = new KeySetupDraftStore(f.Path); drafts.Write(Provider.Gemini,Good); drafts.Expand("Groq"); new SecretStore(f.Path).Clear(); var after = new KeySetupDraftStore(f.Path); Assert.Empty(after.Read(Provider.Gemini)); Assert.Equal("Gemini",after.Expanded()); }
 [Fact] public async Task DraftDebounceCancelsStaleCandidateWithoutStaleSuccess() {
  using var f = new TestFolder(); var first = new TaskCompletionSource(); var started = new TaskCompletionSource(); int calls = 0;
  using var session = new KeySetupSession(Provider.Gemini,new(f.Path),async (_,key,_,_) => { calls++; if (key == Good) { started.SetResult(); await first.Task; } },TimeSpan.Zero);
  var old = session.Update(Good); await started.Task; await session.Update("invalid"); first.SetResult(); await old; Assert.Equal(KeyCheckState.Incomplete,session.State); Assert.False(session.CanSave); Assert.Equal(1,calls);
 }
 [Fact] public async Task DebounceCoalescesRapidTypingAndRequiresVerificationBeforeSaving() {
  using var f = new TestFolder(); int calls = 0; using var session = new KeySetupSession(Provider.Gemini,new(f.Path),(_,_,_,_) => { calls++; return Task.CompletedTask; },TimeSpan.FromMilliseconds(80));
  var one = session.Update(Good); var two = session.Update(Good + "1"); Assert.False(await session.Save((_,_) => throw new InvalidOperationException())); await Task.WhenAll(one,two); Assert.Equal(1,calls); Assert.True(session.CanSave); Assert.True(await session.Save((key,_) => { Assert.Equal(Good + "1",key); return Task.CompletedTask; })); Assert.Empty(new KeySetupDraftStore(f.Path).Read(Provider.Gemini));
 }
 [Fact] public async Task CancellationOnPageExitCannotVerifyOrSave() { using var f = new TestFolder(); var pending = new TaskCompletionSource(); using var session = new KeySetupSession(Provider.Gemini,new(f.Path),(_,_,_,_) => pending.Task,TimeSpan.Zero); var task = session.Update(Good); session.Dispose(); pending.SetResult(); await task; Assert.False(session.CanSave); }
 [Theory][InlineData(400,KeyCheckState.Rejected)][InlineData(401,KeyCheckState.Rejected)][InlineData(403,KeyCheckState.Rejected)][InlineData(429,KeyCheckState.Unverified)][InlineData(503,KeyCheckState.Unverified)]
 public async Task GuidedValidationSeparatesRejectionAndTemporaryFailure(int status,KeyCheckState expected) { using var f = new TestFolder(); using var s = new KeySetupSession(Provider.Gemini,new(f.Path),(_,_,_,_) => throw new ProviderException("provider_error",status),TimeSpan.Zero); await s.Update(Good); Assert.Equal(expected,s.State); Assert.False(s.CanSave); Assert.Equal(Good,new KeySetupDraftStore(f.Path).Read(Provider.Gemini)); }
 [Theory][InlineData(Provider.Gemini,Good,"https://generativelanguage.googleapis.com/v1beta/models")][InlineData(Provider.Groq,"gsk_012345678901234567890","https://api.groq.com/openai/v1/models")][InlineData(Provider.OpenRouter,"sk-or-012345678901234567890","https://openrouter.ai/api/v1/key")]
 public async Task SetupValidationUsesStatusOnlyWithoutModelTokensOrBody(Provider provider,string key,string endpoint) { using var client = new ProviderClient(new MockHttp((request,_) => { Assert.Equal(HttpMethod.Get,request.Method); Assert.Null(request.Content); Assert.Equal(endpoint,request.RequestUri!.AbsoluteUri); if (provider == Provider.Gemini) Assert.Equal(key,Assert.Single(request.Headers.GetValues("x-goog-api-key"))); else Assert.Equal(key,request.Headers.Authorization!.Parameter); return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK) { Content = new StringContent("") }); })); await client.ValidateSetupKey(provider,key,"",CancellationToken.None); }
 [Fact] public async Task KeyOnlySavePreservesSpeechCleanupAndSkipsModelFetch() { using var f = new TestFolder(); var settings = new SettingsStore(f.Path); settings.Value.CleanupAutomatic = false; settings.Value.CleanupProvider = Provider.OpenAI; var secrets = new SecretStore(f.Path); await KeySetupSaving.Save(Provider.Gemini,Good,"","","Added",false,secrets,settings,_ => throw new InvalidOperationException("Must not fetch"),CancellationToken.None); Assert.Equal(Provider.Groq,settings.Value.Provider); Assert.Equal(Provider.OpenAI,settings.Value.CleanupProvider); Assert.Equal(Good,secrets.Read(Provider.Gemini)); }
 [Fact] public async Task SpeechSaveSelectsPreferredFreeModelAndPreservesManualCleanup() { using var f = new TestFolder(); var settings = new SettingsStore(f.Path); settings.Value.CleanupAutomatic = false; settings.Value.CleanupProvider = Provider.OpenAI; var secrets = new SecretStore(f.Path); await KeySetupSaving.Save(Provider.Gemini,Good,"","","",true,secrets,settings,_ => Task.FromResult(new List<ModelOption> {new("paid",false,true),new("free",true)}),CancellationToken.None); Assert.Equal(Provider.Gemini,settings.Value.Provider); Assert.Equal("free",settings.Value.SpeechModel); Assert.Equal(Provider.OpenAI,settings.Value.CleanupProvider); }
 [Fact] public async Task CatalogFailureStillSavesVerifiedKeyAndDefaultModel() { using var f = new TestFolder(); var settings = new SettingsStore(f.Path); await KeySetupSaving.Save(Provider.Gemini,Good,"","","",true,new(f.Path),settings,_ => throw new ProviderException("network"),CancellationToken.None); Assert.Equal(Providers.Get(Provider.Gemini).SpeechModel,settings.Value.SpeechModel); }
 [Fact] public async Task CanceledModelFetchCannotSaveOrActivateKey() { using var f = new TestFolder(); using var cancel = new CancellationTokenSource(); var secrets = new SecretStore(f.Path); var settings = new SettingsStore(f.Path); await Assert.ThrowsAnyAsync<OperationCanceledException>(() => KeySetupSaving.Save(Provider.Gemini,Good,"","","",true,secrets,settings,_ => { cancel.Cancel(); return Task.FromResult(new List<ModelOption>()); },cancel.Token)); Assert.Empty(secrets.List(Provider.Gemini)); Assert.Equal(Provider.Groq,settings.Value.Provider); }
 [Theory][InlineData("Notepad","hello",false)][InlineData("notepad","नमस्ते 🌙",true)][InlineData("chrome","नमस्ते 🌙",false)] public void SupplementaryNotepadTextUsesVerifiedClipboardTransport(string app,string text,bool expected) => Assert.Equal(expected,NativeTextPayload.NeedsClipboard(app,text));
}
